agentflow-beta TB
    connector llm["LLM API"]
    llm@{ protocol: "http", endpoint: "https://api.example.com/chat" }
    global
        guide["Style guide"]@{ shape: refdoc }
    end
    brief["Release brief"]@{ shape: input }
    flow writer["Drafting Agent"]@{ model: "claude-sonnet" }
        draft["Draft the notes"]@{ shape: task }
        search["changelog_search"]@{ shape: tool, connectorRef: "llm.chat" }
        draft --> search
        draft -.- guide
    end
    flow reviewer["Review Agent"]
        check["Accurate?"]@{ shape: decision }
    end
    publish["Publish"]@{ shape: action }
    brief --> draft
    search --> check
    check -- yes --> publish
    check -- no --x draft

zenuml
    title Order
    @Actor Customer
    @Database DB
    Customer->Shop: Place order
    Shop.checkout(cart) {
        stock = DB.reserve(cart)
        if(stock) {
            return confirmed
        } else {
            @return
            Shop->Customer: Out of stock
        }
    }

