railroad-beta
title Expression
/* W3C comment: an expression is terms joined by + or - */
expression = sequence(
    nonterminal("term"),
    zeroOrMore(sequence(
        choice(terminal("+"), terminal("-")),
        nonterminal("term")
    ))
) ;
term = choice(
    oneOrMore(nonterminal("digit")),
    sequence(terminal("("), nonterminal("expression"), terminal(")"))
) ;
digit = choice(terminal("0"), terminal("1"), optional(special("other digits"))) ;

railroad-ebnf-beta
title "Arithmetic"
(* ISO 14977 comment: an expression is terms joined by + or - *)
expression = term ( ( "+" | "-" ) term )* ;
term = factor { ( "*" | "/" ) factor } ;
factor = number | "(" expression ")" ;
number ::= [ "-" ] , digit+ ;
digit = "0" | "1" | "2" | ? other digit ? ;
letter = "a" | "b" | "q" ;
safe = letter - "q" ;

railroad-abnf-beta
title "Email Address"
; ABNF comment: an address is a local part and a domain
address = local-part "@" domain ;
local-part = 1*( ALPHA / DIGIT / "." / "-" ) ;
domain = label *( "." label ) [ ":" 2*5DIGIT ] ;
label = 1*63( ALPHA / DIGIT / "-" ) ;
DIGIT = %x30-39 ;
ALPHA = %x41-5A / %x61-7A ;

railroad-peg-beta
title "Calculator"
# PEG comment: ordered choice tries each alternative in turn
Expression <- Term (("+" / "-") Term)* ;
Term <- Factor (("*" / "/") Factor)* ;
Factor <- Number / "(" Expression ")" ;
Number <- "-"? Digit+ ;
Digit <- "0" / "1" / "2" / "3" ;
Ident <- !Keyword &Letter . Letter* ;
Keyword <- "if" / 'else' ;
Letter <- "a" / "b" ;
